import '../../../globals'
import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Button, Form, Input, Radio, Select, Alert, Spin } from 'antd'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import QueryString from 'query-string'
import EditTemplateStyled from './editTemplate.style'
import NotificationActions from '../../redux/notifications/actions'
import Trumbowyg from 'react-trumbowyg'
import $ from 'jquery'
import { HTMLStyled as HtmlEditorStyled } from './htmlEditor.styled'

const { getMasterData, getTemplateDetail, updateTemplate, resetNotificationsRedux, closeViewBodyHtml, addLanguageTemplate, resetNotificationCore } = NotificationActions

const FormItem = Form.Item
const { TextArea } = Input
const Option = Select.Option
const RadioGroup = Radio.Group

class AddLanguageTemplate extends React.Component {
    state = {
      masterData: {},
      queryString: QueryString.parse(this.props.location.search),
      submitting: false,
      plainTextSelected: true,
      plainEditor: ''
    }
    componentWillReceiveProps (nextProps) {
      const {
        masterData,
        getMasterDataStatus,
        dataDetailTemplate,
        getTemplateDetailStatus,
        addLanguageTemplateStatus
      } = nextProps.Notifications
      if (getMasterDataStatus !== '') {
        this.setState({ masterData, getMasterDataStatus })
      }
      if (addLanguageTemplateStatus !== '') {
        this.setState({ addLanguageTemplateStatus, submitting: false })
      }
      if (getTemplateDetailStatus !== '') {
        this.setState({ dataDetailTemplate, getTemplateDetailStatus, notificationType: dataDetailTemplate.notification_type })
      }
      if (addLanguageTemplateStatus !== '' && addLanguageTemplateStatus === 'success') {
        $('#body').trumbowyg('empty')
        this.props.form.setFieldsValue({
          code: '',
          description: '',
          notification_type: '',
          subject: '',
          body_text: '',
          body: '',
          language_code: ''
        })
        this.props.resetNotificationCore()
      }
    }
    componentDidMount () {
      const { queryString } = this.state
      this.props.getTemplateDetail(queryString)
      this.props.getMasterData()
    }
    componentWillUnmount () {
      this.props.resetNotificationsRedux()
      this.props.closeViewBodyHtml()
    }
    back = () => {
      const { history } = this.props
      history.push('/notifications')
    }
    async validateForm () {
      return new Promise((resolve) => {
        this.props.form.validateFields((error, values) => {
          resolve(!error)
        })
      })
    }
    onSubmit = async e => {
      e.preventDefault()
      this.setState({ submitting: true })
      const valid = await this.validateForm()
      if (!valid) {
        return
      }
      const { form } = this.props
      const { htmlContent, queryString } = this.state
      let data = form.getFieldsValue()
      if (data.body === undefined) {
        data = { ...data, body: htmlContent }
      }
      data = { ...data, tmpl_lang_id: queryString.code, code: queryString.id }
      if (this.state.notificationType === 'sms') {
        data = {
          ...data,
          subject: '',
          id: queryString.id,
          template_code: queryString.code
        }
      }
      if (this.state.plainTextSelected) {
        data = {
          ...data,
          tmpl_lang_id: queryString.code,
          template_code: queryString.id
        }
      }
      this.props.addLanguageTemplate(data)
    }
    handleEditorChange = (e) => {
      this.setState({
        htmlContent: e.target.innerHTML,
        isHtmlEmpty: e.target.innerHTML
      })
    }
    onCloseAlert = () => {
      this.props.resetNotificationsRedux()
      this.setState({ addLanguageTemplateStatus: '' })
    }
    notificationType = notificationType => {
      this.setState({ notificationType })
    }
    onEditorChange = (e) => {
      this.setState({
        plainTextSelected: e.target.value
      })
    }
    onChangeEditorPlain = e => {
      this.setState({ plainEditor: e.target.value })
    }
    getLangugeCodes = () => {
      const { masterData } = this.state
      let languageOptions = ''
      if (masterData.language_codes) {
        languageOptions = masterData.language_codes.map(d => (<Option value={d.code} key={d.id}>{d.description}</Option>
        ))
      }
      return languageOptions
    }
    render () {
      const { masterData, submitting, dataDetailTemplate } = this.state
      const { form } = this.props
      const { getFieldDecorator } = form
      const radioStyle = {
        display: 'block',
        height: '30px',
        lineHeight: '30px'
      }
      let htmlEditor = <Trumbowyg
        data=''
        id='react-trumbowyg'
        onChange={this.handleEditorChange}
      />

      if (this.state.notificationType === 'sms') {
        htmlEditor = <Input />
      }
      const isSms = this.state.notificationType === 'sms'
      let subjectStyle = {}
      if (isSms) {
        subjectStyle = {
          visibility: 'hidden'
        }
      }
      return (
        <LayoutContentWrapper>
          {
            (this.state.addLanguageTemplateStatus !== '' && this.state.addLanguageTemplateStatus === 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.addLanguageTemplateStatus}
                    type={'success'}
                    closable
                    onClose={this.onCloseAlert}
                  />
                </Col>
              </Row>
            )
          }
          {
            (this.state.addLanguageTemplateStatus !== '' && this.state.addLanguageTemplateStatus !== undefined && this.state.addLanguageTemplateStatus !== 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.addLanguageTemplateStatus}
                    type={'error'}
                    closable
                    onClose={this.onCloseAlert}
                  />
                </Col>
              </Row>
            )
          }
          <LayoutContent>
            <EditTemplateStyled>
              <Row>
                <Col span={24} xs={24}>
                  <Button onClick={this.back}>Back</Button>
                </Col>
                <Spin spinning={this.state.submitting}>
                  <Form
                    onSubmit={this.onSubmit}
                    style={{ marginTop: '20px' }}
                    id='addTemplate'
                  >
                    <Row gutter={24}>
                      <Col span={24} xs={24}>
                        <FormItem
                          label='Unique template code'
                          extra='eg: tmpl-claim-creation-email-01'
                        >
                          {getFieldDecorator('code', {
                            rules: [
                              { required: true, message: 'Unique template code can not be empty' }
                            ],
                            initialValue: this.state.queryString.id
                          })(
                            <Input size='default' className='input-box' disabled />
                          )}
                        </FormItem>
                        <FormItem
                          label='Language'
                        >
                          {getFieldDecorator('language_code', {
                            rules: [
                              { required: true, message: 'language_code can not be empty' }
                            ]
                          })(
                            <Select
                              showSearch
                              placeholder='Select ...'
                              style={{ width: '100%' }}
                              filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                            >
                              {this.getLangugeCodes()}
                            </Select>
                          )}
                        </FormItem>
                        <FormItem
                          label='Description'
                        >
                          {getFieldDecorator('description', {
                            rules: [
                              { required: true, message: 'Description can not be empty' }
                            ],
                            initialValue: dataDetailTemplate !== undefined ? dataDetailTemplate.description : ''
                          })(
                            <Input size='default' className='input-box' disabled />
                          )}
                        </FormItem>
                        <FormItem
                          label='Type'
                        >
                          {getFieldDecorator('notification_type', {
                            rules: [
                              { required: true, message: 'Notification type can not be empty' }
                            ],
                            initialValue: dataDetailTemplate !== undefined ? dataDetailTemplate.notification_type : ''
                          })(
                            <Select
                              disabled
                              showSearch
                              placeholder='Select ...'
                              style={{ width: '100%' }}
                              filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                              onChange={this.notificationType}
                            >
                              {
                                masterData.notification_types !== undefined ? masterData.notification_types.map((value, index) => {
                                  return <Option key={index} value={value}>{value}</Option>
                                }) : <Option key={1} value={'loading ...'} disabled>Loading ...</Option>
                              }
                            </Select>
                          )}
                        </FormItem>

                        <div style={subjectStyle}>
                          <FormItem
                            label='Subject'
                            style={{ marginBottom: '20px' }}
                          >
                            {getFieldDecorator('subject', {
                              rules: [
                                { required: !isSms, message: 'Subject can not be empty' }
                              ]
                            })(
                              <Input size='default' className='input-box' />
                            )}
                          </FormItem>
                        </div>
                      </Col>
                      <RadioGroup onChange={this.onEditorChange} value={this.state.plainTextSelected} style={{ marginLeft: '15px' }} >
                        <Radio style={radioStyle} value>PLAIN HTML</Radio>
                        <Radio style={radioStyle} value={false}>HTML EDITOR</Radio>
                      </RadioGroup>
                      <Col span={24} xs={24}>
                        <HtmlEditorStyled isEmpty={this.state.isHtmlEmpty} isSubmit={this.state.submit}>
                          <label className='custom-label' style={{ marginBottom: '10px' }}>Body {this.state.notificationType === 'sms' ? 'SMS' : 'HTML'}</label>
                          <FormItem style={{ marginBottom: '20px' }}>
                            {getFieldDecorator('body', {
                              rules: [
                                { required: false, message: 'Main body can not be empty' }
                              ]
                            })(this.state.plainTextSelected ? (<TextArea onChange={this.onChangeEditorPlain} autosize={{ minRows: 10, maxRows: 20 }} style={{ marginTop: '20px' }} />) : htmlEditor)}
                          </FormItem>
                        </HtmlEditorStyled>
                      </Col>
                      {
                        this.state.notificationType !== 'sms' && (
                          <Col span={24} xs={24}>
                            <label className='custom-label'>Body (Text)</label>
                            <FormItem>
                              {getFieldDecorator('body_text', {
                                rules: [
                                  { required: false }
                                ]
                              })(
                                <TextArea
                                  autosize={{ minRows: 10, maxRows: 20 }}
                                />
                              )}
                            </FormItem>
                          </Col>
                        )
                      }
                    </Row>
                  </Form>
                </Spin>
                <Col span={24} xs={24}>
                  <div style={{ textAlign: 'right', marginTop: '20px' }}>
                    <Button
                      key='submit'
                      type='primary'
                      form='addTemplate'
                      htmlType='submit'
                      loading={submitting}
                      style={{ marginLeft: '10px' }}
                    >
                                            Submit
                    </Button>
                  </div>
                </Col>
              </Row>
            </EditTemplateStyled>
          </LayoutContent>
        </LayoutContentWrapper>
      )
    }
}

const WrappedForm = Form.create({})(AddLanguageTemplate)

export default connect(
  state => ({
    Notifications: state.Notifications
  }),
  { getMasterData, updateTemplate, getTemplateDetail, resetNotificationsRedux, closeViewBodyHtml, addLanguageTemplate, resetNotificationCore }
)(WrappedForm)
